function tileKey(x, y) {
  return `${x | 0},${y | 0}`;
}

function buildTileOccupants(world) {
  /** @type {Map<string, number[]>} */
  const byTile = new Map();
  for (const [id, pos] of world.query(Position)) {
    const k = tileKey(pos.x, pos.y);
    if (!byTile.has(k)) byTile.set(k, []);
    byTile.get(k).push(id);
  }
  return byTile;
}

function resolveMissRayImpact(world, { attacker, defender, from, intended, missTo, isBlocked }) {
  const fx = Number(from?.x || 0) | 0;
  const fy = Number(from?.y || 0) | 0;
  const tx = Number(intended?.x || 0);
  const ty = Number(intended?.y || 0);
  const mx = Math.round(Number(missTo?.x || tx));
  const my = Math.round(Number(missTo?.y || ty));
  const aimDx = tx - fx;
  const aimDy = ty - fy;
  const aimLen = Math.hypot(aimDx, aimDy) || 1;
  const ux = aimDx / aimLen;
  const uy = aimDy / aimLen;
  const byTile = buildTileOccupants(world);
  const attackerFaction = String(world.get(attacker, Faction)?.key || '');

  for (const [x, y] of bresenhamLine(fx, fy, mx, my)) {
    if (isBlocked(x, y)) {
      return { kind: 'wall', x, y, hitTargetId: 0 };
    }

    const ids = byTile.get(tileKey(x, y));
    if (!ids || ids.length === 0) continue;

    let blocker = 0;
    for (let i = 0; i < ids.length; i++) {
      const id = ids[i] | 0;
      if (id === attacker) continue;
      const pos = world.get(id, Position);
      if (!pos) continue;
      const forward = ((Number(pos.x) - fx) * ux) + ((Number(pos.y) - fy) * uy);
      if (forward <= (aimLen + 0.01)) continue; // only allow targets behind intended endpoint

      const vit = world.get(id, Vitality);
      const hp = Number(vit?.hp || 0);
      const col = world.get(id, Collider);
      const fac = String(world.get(id, Faction)?.key || '');
      if (id !== defender && hp > 0 && areFactionsHostile(attackerFaction, fac)) {
        return { kind: 'entity', x: pos.x | 0, y: pos.y | 0, hitTargetId: id };
      }
      if (id !== defender && (hp > 0 || !!col?.solid)) blocker = id;
    }
    if (blocker > 0) return { kind: 'entity-block', x, y, hitTargetId: 0, blockerId: blocker };
  }
  return null;
}
import { HazardArea } from "../components/HazardArea.js";
import { NamedIdentity } from "../components/NamedIdentity.js";
import { Position } from "../components/Position.js";
import { attachEntityToCurrentFloor } from "./floorEntities.js";
import { clampInt } from "./numberCoerce.js";

const DEFAULT_TURNS = 3;
const DEFAULT_RADIUS = 1;
const DEFAULT_TICK_DAMAGE = 0;

function normalizeMedium(value) {
  const medium = String(value || "").toLowerCase();
  if (medium === "floor") return "floor";
  return "air";
}

function titleCase(text) {
  const src = String(text || "");
  if (!src) return "";
  return `${src.slice(0, 1).toUpperCase()}${src.slice(1)}`;
}

/**
 * Track runtime-created hazards as floor-owned entities so transitions can
 * serialize/destroy them with the rest of the current floor.
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} entityId
 */
/**
 * Generic hazard spawner for air/floor AoE entities.
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {{
 *   x:number,
 *   y:number,
 *   kind?:string,
 *   medium?:'air'|'floor'|string,
 *   turnsLeft?:number,
 *   radius?:number,
 *   tickDamage?:number,
 *   damage?:number,
 *   damageType?:string,
 *   cause?:string,
 *   sourceId?:number,
 *   sourceKind?:string,
 *   identity?:string,
 *   name?:string,
 *   meta?:Record<string, unknown>|null,
 * }} params
 */
export function spawnHazard(world, params) {
  if (!world || !params) return 0;

  const x = Number.isFinite(params.x) ? (params.x | 0) : 0;
  const y = Number.isFinite(params.y) ? (params.y | 0) : 0;
  const kind = String(params.kind || "generic").toLowerCase() || "generic";
  const medium = normalizeMedium(params.medium);
  const turnsLeft = clampInt(params.turnsLeft, DEFAULT_TURNS, 1);
  const radius = clampInt(params.radius, DEFAULT_RADIUS, 0);
  const tickDamage = clampInt(
    Number.isFinite(params.tickDamage) ? params.tickDamage : params.damage,
    DEFAULT_TICK_DAMAGE,
    0,
  );
  const damageType = String(params.damageType || "generic").toLowerCase() || "generic";
  const cause = String(params.cause || `${kind}_hazard`);
  const sourceId = clampInt(params.sourceId, 0, 0);
  const sourceKind = typeof params.sourceKind === "string" ? params.sourceKind : "";
  const identity = String(params.identity || `${kind}_hazard`) || `${kind}_hazard`;
  const name = String(params.name || `${titleCase(kind)} Hazard`) || `${titleCase(kind)} Hazard`;
  const meta = (params.meta && typeof params.meta === "object" && !Array.isArray(params.meta))
    ? { ...params.meta }
    : null;

  const hazardId = world.create();
  world.add(hazardId, Position, { x, y });
  world.add(hazardId, HazardArea, {
    kind,
    medium,
    turnsLeft,
    radius,
    tickDamage,
    damageType,
    cause,
    sourceId,
    sourceKind,
    meta,
  });
  try { world.add(hazardId, NamedIdentity, { name, identity }); } catch { /* */ }
  attachEntityToCurrentFloor(world, hazardId);

  try {
    world.emit?.("hazard:spawned", {
      hazardId,
      kind,
      medium,
      at: { x, y },
      turnsLeft,
      radius,
      tickDamage,
      damageType,
      cause,
      sourceId,
      sourceKind,
      identity,
      name,
    });
  } catch { /* */ }

  // Plasma compatibility bridge for existing listeners/tests.
  if (kind === "plasma") {
    try {
      world.emit?.("plasmaCloud:spawned", {
        cloudId: hazardId,
        at: { x, y },
        turnsLeft,
        radius,
        damage: tickDamage,
        sourceId,
        sourceKind,
      });
    } catch { /* */ }
  }

  return hazardId;
}
}

function isFlammableFireSpreadTile(world, x, y, tile, overworld) {
  if (tile === TILE_TREE) return true;
  if (!overworld) return false;
  if (isRoofFuelTile(world, x, y, tile, overworld)) return true;
  return tile === TILE_FENCE || tile === TILE_DOOR || tile === TILE_WALL;
}

function burnFlammableEntitiesAt(world, x, y, source, hazardId, cause, sourceId, sourceKind) {
  for (const [id, pos, mat] of world.query(Position, Material)) {
    if (!pos || !mat) continue;
    if ((pos.x | 0) !== (x | 0) || (pos.y | 0) !== (y | 0)) continue;
    if (world.has(id, Vitality)) continue;
    if (world.has(id, Burned)) continue;
    const ident = world.get(id, NamedIdentity);
    const isWeb = String(ident?.identity || "").toLowerCase() === WEB_IDENTITY;
    const stimulus = applyMaterialStimulus(world, id, {
      kind: "fire",
      mode: "hazard_contact",
      intensity: 3,
      duration: 1,
    });
    const transform = resolveMaterialTransform({
      stimulusKind: "fire",
      requestedTransform: "ash",
      identity: String(ident?.identity || ""),
      state: stimulus?.state,
    });
    if (!isWeb && transform !== "ash") continue;
    try {
      world.emit?.("entity:burned", {
        actor: source,
        hazardId,
        entityId: id,
        x: x | 0,
        y: y | 0,
        cause,
        sourceId,
        sourceKind,
        identity: String(ident?.identity || ""),
        name: String(ident?.name || ""),
        material: String(mat.kind || ""),
      });
    } catch { /* */ }
    if (world.has(id, ItemInfo)) {
      try { applyMaterialTransform(world, id, "ash"); } catch { /* */ }
    } else {
      try {
        const ashId = createFrom(world, Ashes, {});
        world.add(ashId, Position, { x: x | 0, y: y | 0 });
      } catch { /* */ }
    }
    try {
      world.add(id, Burned, {
        atTurn: world.step | 0,
        cause,
        sourceId,
        sourceKind,
        smokeTurnsLeft: 6,
      });
    } catch { /* */ }
    try { if (world.has(id, Collider)) world.remove(id, Collider); } catch { /* */ }
    try { if (world.has(id, Interactable)) world.remove(id, Interactable); } catch { /* */ }
  }
}

function clampChance(value, fallback) {
  return clamp01Or(value, fallback);
}

function getFireSpreadChance(hazard) {
  return clampChance(hazard?.meta?.fireSpreadChance, DEFAULT_FIRE_SPREAD_CHANCE);
}

function getFireSpreadTurns(hazard, turnsBefore) {
  return clampInt(hazard?.meta?.fireSpreadTurns, Math.max(1, turnsBefore - 1), 1);
}

function hasEquippedTorch(world, actorId) {
  const eq = world.get(actorId, Equipment);
  if (!eq) return false;
  for (let i = 0; i < NON_AMMO_GEAR_SLOTS.length; i++) {
    const itemId = Number(eq[NON_AMMO_GEAR_SLOTS[i]] || 0) | 0;
    if (!(itemId > 0)) continue;
    const info = world.get(itemId, ItemInfo);
    if (String(info?.id || "") === "torch") return true;
  }
  return false;
}

function hazardMetric(hazard, identity) {
  const metric = String(hazard?.meta?.distanceMetric || "").toLowerCase();
  if (metric === "euclidean") return "euclidean";
  if (String(identity || "") === "explosive_gas") return "euclidean";
  return "chebyshev";
}

function inHazardRadius(x, y, cx, cy, radius, metric) {
  const dx = Math.abs((x | 0) - (cx | 0));
  const dy = Math.abs((y | 0) - (cy | 0));
  if (metric === "euclidean") return (dx * dx + dy * dy) <= (radius * radius);
  return Math.max(dx, dy) <= radius;
}

function hasBurningEffect(effects) {
  if (!effects || !Array.isArray(effects.effects)) return false;
  for (let i = 0; i < effects.effects.length; i++) {
    const key = String(effects.effects[i]?.key || "").toLowerCase();
    if (key === "burn" || key === "burning") return true;
  }
  return false;
}

function ensureActiveEffectRecord(world, entityId) {
  let ae = /** @type any */ (world.get(entityId, ActiveEffects));
  if (!ae) {
    try { world.add(entityId, ActiveEffects, { effects: [] }); } catch { /* */ }
    ae = /** @type any */ (world.get(entityId, ActiveEffects));
  }
  if (!ae || !Array.isArray(ae.effects)) return null;
  return ae;
}

function applyStickySyrup(world, entityId, sourceId, turnsLeft, potency) {
  const ae = ensureActiveEffectRecord(world, entityId);
  if (!ae) return false;
  upsertTimedEffect(ae.effects, {
    key: "slowed",
    turnsLeft,
    potency,
    stacks: 1,
    sourceId,
    startedAtTurn: world.step | 0,
  });
  return true;
}

function gasHazardShouldIgnite(world, x, y, radius, metric) {
  const gasRadius = Math.max(0, radius | 0);
  for (const [, firePos, fireHazard] of world.query(Position, HazardArea)) {
    if (!firePos || !fireHazard) continue;
    if (String(fireHazard.kind || "").toLowerCase() !== "fire") continue;
    if ((Number(fireHazard.turnsLeft || 0) | 0) <= 0) continue;
    const fireRadius = clampInt(fireHazard.radius, 0, 0);
    if (inHazardRadius(firePos.x, firePos.y, x, y, gasRadius + fireRadius + 1, metric)) return true;
  }
  for (const [, actorPos, effects] of world.query(Position, ActiveEffects)) {
    if (!actorPos || !hasBurningEffect(effects)) continue;
    if (inHazardRadius(actorPos.x, actorPos.y, x, y, gasRadius, metric)) return true;
  }
  for (const [actorId, actorPos] of world.query(Position, Equipment)) {
    if (!actorPos) continue;
    if (!hasEquippedTorch(world, actorId)) continue;
    if (inHazardRadius(actorPos.x, actorPos.y, x, y, gasRadius, metric)) return true;
  }
  return false;
}

/**
