    const fenceScar = getDestroyedTileRecord(world, 7, 5);
    assert(fenceScar, "fence burn should persist its original tile");
    assertEquals(fenceScar.originalTile, TILE_FENCE);
    assertEquals(fenceScar.roofTurnsLeft, 0);
  } finally {
    clearAll();
  }
});

